local ServiceDescriptor = require(script.Parent.ServiceDescriptor)

type ImplementationType = string | ModuleScript | IServiceFactory

local ServiceCollection = {}
ServiceCollection.__index = ServiceCollection

function ServiceCollection.new()
	local self = setmetatable({}, ServiceCollection)
	self._descriptors = {}
	self._isReadOnly = false
	return self
end

function ServiceCollection:Add(item: IServiceDescriptor)
	self:CheckReadOnly()
	table.insert(self._descriptors, item)
end

function ServiceCollection:Clear()
	self:CheckReadOnly()
	self._descriptors = {}
end

function ServiceCollection:Count()
	return #self._descriptors
end

function ServiceCollection:Contains(item: IServiceDescriptor)
	for _, v in ipairs(self._descriptors) do
		if v == item then
			return true
		end
	end
	return false
end

function ServiceCollection:ContainsService(serviceType: string)
	for _, v in ipairs(self._descriptors) do
		if v.ServiceType == serviceType then
			return true
		end
	end
	return false
end

function ServiceCollection:Remove(item: IServiceDescriptor)
	self:CheckReadOnly()
	for i, v in ipairs(self._descriptors) do
		if v == item then
			table.remove(self._descriptors, i)
			return true
		end
	end
	return false
end

function ServiceCollection:IndexOf(item: IServiceDescriptor)
	for i, v in ipairs(self._descriptors) do
		if v == item then
			return i
		end
	end
	return -1
end

function ServiceCollection:Insert(index: number, item: IServiceDescriptor)
	self:CheckReadOnly()
	table.insert(self._descriptors, index, item)
end

function ServiceCollection:RemoveAt(index)
	self:CheckReadOnly()
	table.remove(self._descriptors, index)
end

function ServiceCollection:MakeReadOnly()
	self._isReadOnly = true
end

function ServiceCollection:CheckReadOnly()
	if self._isReadOnly then
		error("Service Collection Read Only")
	end
end

function ServiceCollection:TryAddTransient(serviceType: string, implementation: ImplementationType)
	return self:AddTransient(serviceType, implementation, true)
end

function ServiceCollection:TryAddScoped(serviceType: string, implementation: ImplementationType)
	return self:AddScoped(serviceType, implementation, true)
end

function ServiceCollection:TryAddSingleton(serviceType: string, implementation: ImplementationType)
	return self:AddSingleton(serviceType, implementation, true)
end

function ServiceCollection:TryAddHostedService(implementation: ImplementationType)
	return self:AddHostedService(implementation, nil)
end

function ServiceCollection:AddTransient(serviceType: string, implementation: ImplementationType, isTryAdd: boolean?)
	local lifetime = "Transient"
	local descriptor = ServiceDescriptor.newWithVarient(serviceType, implementation, lifetime)
	if isTryAdd and self:ContainsService(serviceType) then
		return self
	else
		self:Add(descriptor)
		return self
	end
end

function ServiceCollection:AddHostedService(implementation: ImplementationType, alias: string?)
	local lifetime = "Singleton"
	if alias then
		local descriptor = ServiceDescriptor.newWithVarient(alias, implementation, lifetime)
		self:Add(descriptor)
		local descriptor = ServiceDescriptor.newWithVarient("IHostedService", function(serviceProvider)
			return serviceProvider:GetRequiredService(alias)
		end, lifetime)
		self:Add(descriptor)
	else
		local descriptor = ServiceDescriptor.newWithVarient("IHostedService", implementation, lifetime)
		self:Add(descriptor)
	end

	return self
end

function ServiceCollection:AddScoped(serviceType: string, implementation: ImplementationType, isTryAdd: boolean?)
	local lifetime = "Scoped"
	local descriptor = ServiceDescriptor.newWithVarient(serviceType, implementation, lifetime)
	if isTryAdd and self:ContainsService(serviceType) then
		return self
	else
		self:Add(descriptor)
		return self
	end
end

function ServiceCollection:AddSingleton(serviceType: string, implementation: ImplementationType, isTryAdd: boolean?)
	local lifetime = "Singleton"
	local descriptor = ServiceDescriptor.newWithVarient(serviceType, implementation, lifetime)
	if isTryAdd and self:ContainsService(serviceType) then
		return self
	else
		self:Add(descriptor)
		return self
	end
end

-- 添加泛型版本的方法
function ServiceCollection:AddTransientGeneric(serviceType, implementationType)
	error("not implemented")
end

function ServiceCollection:AddScopedGeneric(serviceType, implementationType)
	error("not implemented")
end

function ServiceCollection:AddSingletonGeneric(serviceType, implementationType)
	error("not implemented")
end

export type Type = typeof(ServiceCollection:new())

return ServiceCollection
